sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        //Updated as part of MSSOTIQUBE-1902 and 2042
        var agentCorrelator = current.response_to.agent_correlator.toString();
        var splitArr = agentCorrelator.split("/");
        var trade_sys_id;
        var sys_id = splitArr[0];
        var Form = splitArr[1];
        if (Form == "TaskForm") {
            var Task = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            Task.get(sys_id);
            trade_sys_id = Task.trade_id;
        } else {
            trade_sys_id = sys_id;
        }
        var response = "";

        var xmlDoc = new XMLDocument2();
        xmlDoc.parseXML(current.payload.toString());

        response = xmlDoc.getNodeText("//result/output");
        var httpCodeNode = xmlDoc.getNode("//parameters/parameter");
        var httpCode = httpCodeNode.getAttribute('value');

        if (Form == "TradeForm") {
            if (httpCode == "200") {
                // Got success from both API-1902
                try {
                    var tradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    if (tradeData.get(trade_sys_id)) {
                        tradeData.position_attribute_sync = "Response Success-All fields updated(200)";
                        tradeData.last_positions_refresh_date_time = new GlideDateTime();
                        tradeData.update();
                        //Parse the response and add the details in all the position details records
                        var responsebody = response.toString();
                        var respBodySum = JSON.parse(responsebody);
                        var positionDetail = new GlideRecord("x_hsb11_mss_pos_custody_positions_details");
                        positionDetail.addQuery('trade_id', trade_sys_id);
                        positionDetail.query();
                        while (positionDetail.next()) {
                            positionDetail.available_balance = respBodySum.data[0].balances.available.quantity;
                            positionDetail.traded_balance = respBodySum.data[0].balances.traded.quantity;
                            positionDetail.settled_balance = respBodySum.data[0].balances.settled.quantity;
                            positionDetail.update();
                        }
                    }
                } catch (err) {
                    gs.info("1902" + err.message);
                }

                var grPosOnDemandSummary = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
                grPosOnDemandSummary.addEncodedQuery('refresh_end_timeISEMPTY^trade_reference=' + trade_sys_id);
                grPosOnDemandSummary.query();
                if (grPosOnDemandSummary.next()) {
                    grPosOnDemandSummary.refresh_end_time = new GlideDateTime();
                    grPosOnDemandSummary.response_body_for_summary = response;
                    grPosOnDemandSummary.update();
                }

            } else {
                var tradeDataErr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                if (tradeDataErr.get(trade_sys_id)) {
                    tradeDataErr.position_attribute_sync = "Response Un-Successful - Error";
                    tradeDataErr.last_positions_refresh_date_time = new GlideDateTime();
                    tradeDataErr.update();
                }

                var grPosOnDemandSummaryErr = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
                grPosOnDemandSummaryErr.addEncodedQuery('refresh_end_timeISEMPTY^trade_reference=' + trade_sys_id);
                grPosOnDemandSummaryErr.query();
                if (grPosOnDemandSummaryErr.next()) {
                    grPosOnDemandSummaryErr.refresh_end_time = new GlideDateTime();
                    grPosOnDemandSummaryErr.response_body_for_summary = response;
                    grPosOnDemandSummaryErr.state_for_summary = 'error'; //Retry Mechanism
                    grPosOnDemandSummaryErr.update();
                }
            }

            //Not updating the state_for_summary since it will trigger a existing BR
        } else if (Form == "TradeFormPassive") {

            if (httpCode == "200") {
                // Got success from both API-1902
                try {
                    var tradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
                    if (tradeData.get(trade_sys_id)) {
                        tradeData.position_attribute_sync = "Response Success-All fields updated(200)";
                        tradeData.last_positions_refresh_date_time = new GlideDateTime();
                        tradeData.update();
                        //Parse the response and add the details in all the position details records
                        var responsebody = response.toString();
                        var respBodySum = JSON.parse(responsebody);
                        var positionDetail = new GlideRecord("x_hsb11_mss_pos_custody_positions_details");
                        positionDetail.addQuery('trade_id', trade_sys_id);
                        positionDetail.query();
                        while (positionDetail.next()) {
                            positionDetail.available_balance = respBodySum.data[0].balances.available.quantity;
                            positionDetail.traded_balance = respBodySum.data[0].balances.traded.quantity;
                            positionDetail.settled_balance = respBodySum.data[0].balances.settled.quantity;
                            positionDetail.update();
                        }
                    }
                } catch (err) {
                    gs.info("1902" + err.message);
                }

                var grPosOnDemandSummary = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
                grPosOnDemandSummary.addEncodedQuery('refresh_end_timeISEMPTY^trade_base=' + trade_sys_id);
                grPosOnDemandSummary.query();
                if (grPosOnDemandSummary.next()) {
                    grPosOnDemandSummary.refresh_end_time = new GlideDateTime();
                    grPosOnDemandSummary.response_body_for_summary = response;
                    grPosOnDemandSummary.update();
                }

            } else {
                var tradeDataErr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
                if (tradeDataErr.get(trade_sys_id)) {
                    tradeDataErr.position_attribute_sync = "Response Un-Successful - Error";
                    tradeDataErr.last_positions_refresh_date_time = new GlideDateTime();
                    tradeDataErr.update();
                }

                var grPosOnDemandSummaryErr = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
                grPosOnDemandSummaryErr.addEncodedQuery('refresh_end_timeISEMPTY^trade_base=' + trade_sys_id);
                grPosOnDemandSummaryErr.query();
                if (grPosOnDemandSummaryErr.next()) {
                    grPosOnDemandSummaryErr.refresh_end_time = new GlideDateTime();
                    grPosOnDemandSummaryErr.response_body_for_summary = response;
                    grPosOnDemandSummaryErr.state_for_summary = 'error'; //Retry Mechanism
                    grPosOnDemandSummaryErr.update();
                }
            }




        }




        // MSSOTIQUBE - 2406 - OnDemand Refresh Holding data from task form
        else if (Form == "TaskForm") {
            if (httpCode == "200") {
                // Got success from both API-1902
                try {
                    var taskData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                    taskData.get(sys_id);
                    var tradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    if (tradeData.get(trade_sys_id)) {
                        tradeData.position_attribute_sync = "Response Success-All fields updated(200)";
                        tradeData.last_positions_refresh_date_time = new GlideDateTime();
                        tradeData.update();

                        taskData.position_attribute_sync = "Response Success-All fields updated(200)";
                        taskData.last_positions_refresh_date_time = new GlideDateTime();
                        taskData.update();


                        //Parse the response and add the details in all the position details records
                        var responsebody = response.toString();
                        var respBodySum = JSON.parse(responsebody);
                        var positionDetail = new GlideRecord("x_hsb11_mss_pos_custody_positions_details");
                        positionDetail.addQuery('trade_id', trade_sys_id);
                        positionDetail.query();
                        while (positionDetail.next()) {
                            positionDetail.available_balance = respBodySum.data[0].balances.available.quantity;
                            positionDetail.traded_balance = respBodySum.data[0].balances.traded.quantity;
                            positionDetail.settled_balance = respBodySum.data[0].balances.settled.quantity;
                            positionDetail.update();
                        }
                    }
                } catch (err) {
                    gs.info("1902" + err.message);
                }

                var grPosOnDemandSummary = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
                grPosOnDemandSummary.addQuery("task_reference", sys_id);
                grPosOnDemandSummary.addEncodedQuery('refresh_end_timeISEMPTY^trade_reference=' + trade_sys_id);
                grPosOnDemandSummary.query();
                if (grPosOnDemandSummary.next()) {
                    grPosOnDemandSummary.refresh_end_time = new GlideDateTime();
                    grPosOnDemandSummary.response_body_for_summary = response;
                    grPosOnDemandSummary.update();
                }

            } else {
                var tradeDataErr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                if (tradeDataErr.get(trade_sys_id)) {
                    tradeDataErr.position_attribute_sync = "Response Un-Successful - Error";
                    tradeDataErr.last_positions_refresh_date_time = new GlideDateTime();
                    tradeDataErr.update();
                }

                var taskDataErr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                if (taskDataErr.get(sys_id)) {
                    taskDataErr.position_attribute_sync = "Response Un-Successful - Error";
                    taskDataErr.last_positions_refresh_date_time = new GlideDateTime();
                    taskDataErr.update();
                }

                var grPosOnDemandSummaryErr = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
                grPosOnDemandSummaryErr.addQuery('task_reference', sys_id);
                grPosOnDemandSummaryErr.addEncodedQuery('refresh_end_timeISEMPTY^trade_reference=' + trade_sys_id);
                grPosOnDemandSummaryErr.query();
                if (grPosOnDemandSummaryErr.next()) {
                    grPosOnDemandSummaryErr.refresh_end_time = new GlideDateTime();
                    grPosOnDemandSummaryErr.response_body_for_summary = response;
                    grPosOnDemandSummaryErr.state_for_summary = 'error'; //Retry Mechanism
                    grPosOnDemandSummaryErr.update();
                }
            }

            //Not updating the state_for_summary since it will trigger a existing BR
        } else {
            //Updated as part of MSSOTIQUBE-1902
            //IF called from any other flow like Task. The trade_sys_id will have position OnDemand record's sysid.
            var pos_demand_id = trade_sys_id;
            var grMssCustodyPosOndemandSummary = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
            grMssCustodyPosOndemandSummary.get(pos_demand_id);
            grMssCustodyPosOndemandSummary.response_date_summary = current.sys_updated_on;
            grMssCustodyPosOndemandSummary.response_body_for_summary = response;
            grMssCustodyPosOndemandSummary.response_code_for_summary = httpCode;
            if (httpCode == '200') {
                grMssCustodyPosOndemandSummary.state_for_summary = "processed";
            } else {
                grMssCustodyPosOndemandSummary.state_for_summary = "error";
                grMssCustodyPosOndemandSummary.error_body_for_summary = response;
            }
            grMssCustodyPosOndemandSummary.update();
        }




    } catch (e) {
        gs.info(e.message);
    }

})(current, previous);
